export const CATEGORIES: CategoryMeta[] = Array.from(new Set(PRODUCTS.map((p) => p.category))).map((name) => ({
  name,
  slug: slugify(name),
  count: PRODUCTS.filter((p) => p.category === name).length,
  ...(COPY[name] ?? { ...COPY.Other, short: name, tagline: name }),
}));

export const categoryBySlug = (slug: string | null | undefined): CategoryMeta | undefined =>
  CATEGORIES.find((c) => c.slug === slug);

export interface ProductGroup {
  key: string;
  name: string;
  category: string;
  items: Product[];
}

/** Groups rows by (category, name) so each item shows its sizes as sub-rows. */
export function groupProducts(list: Product[]): ProductGroup[] {
  const groups = new Map<string, ProductGroup>();
  for (const p of list) {
    const key = `${p.category}::${p.name.toLowerCase()}`;
    let g = groups.get(key);
    if (!g) {
      g = { key, name: p.name, category: p.category, items: [] };
      groups.set(key, g);
    }
    g.items.push(p);
  }
  return [...groups.values()];
}

export interface FeaturedItem {
  name: string;
  slug: string;
  sizes: string[];
  packTypes: PackType[];
}

/** Featured items for the showcase: distinct names in a category with their available sizes. */
export function featuredFor(category: string, max = 6): FeaturedItem[] {
  return groupProducts(PRODUCTS.filter((p) => p.category === category))
    .slice(0, max)
    .map((g) => ({
      name: g.name,
      slug: slugify(g.name),
      sizes: Array.from(new Set(g.items.map((i) => i.weight))),
      packTypes: Array.from(new Set(g.items.map((i) => i.packType).filter((t): t is PackType => t !== null))),
    }));
}

/** Dominant pack type of a category (used to choose the placeholder illustration). */
export function dominantPack(category: string): PackType {
  const counts = new Map<PackType, number>();
  for (const p of PRODUCTS) if (p.category === category && p.packType) counts.set(p.packType, (counts.get(p.packType) ?? 0) + 1);
  let best: PackType = 'Printed Pouch';
  let max = -1;
  for (const [k, v] of counts) if (v > max) [best, max] = [k, v];
  return best;
}

export const STATS = {
  products: PRODUCTS.length,
  categories: CATEGORIES.length,
  packFormats: new Set(PRODUCTS.map((p) => p.packType).filter(Boolean)).size,
  bulkItems: PRODUCTS.filter((p) => p.category === 'Bulk Orders').length,
};
